import os
#
import mlx.core as mx
#

TEACHER_DIR = os.path.join("..", "..", "data", "teacher")
TOP_K = 100

#

def topk_logits(logits, k = TOP_K):
    # Sparse logit saving: keep the raw top-K logits and their token ids per position.
    # Getting the index and value; code generated by Claude, manually verified for error
    idx = mx.argpartition(-logits, kth = k - 1, axis = -1)[..., :k]
    vals = mx.take_along_axis(logits, idx, axis = -1)
    order = mx.argsort(-vals, axis = -1)
    # 
    return mx.take_along_axis(vals, order, axis = -1), mx.take_along_axis(idx, order, axis = -1)

def save_teacher_topk(name, logits, k = TOP_K, teacher_dir = TEACHER_DIR):
    # Sanity Check
    os.makedirs(teacher_dir, exist_ok = True)
    # 
    vals, ids = topk_logits(logits, k)
    # 
    mx.savez(os.path.join(teacher_dir, f"{name}.npz"), values = vals.astype(mx.float16), indices = ids.astype(mx.int32))

def load_teacher_topk(name, teacher_dir = TEACHER_DIR):
    f = mx.load(os.path.join(teacher_dir, f"{name}.npz"))
    # 
    return f["values"].astype(mx.float32), f["indices"]
